codeExamples.code:
-- Create a catalog with a managed storage location (optional per-catalog isolation)
CREATE CATALOG IF NOT EXISTS prod
  MANAGED LOCATION 's3://company-lake/uc/prod'
  COMMENT 'Production data products';

-- Create a schema (database) within the catalog
CREATE SCHEMA IF NOT EXISTS prod.sales
  COMMENT 'Curated sales domain';

-- Traversal privileges: needed at each level to reach child objects
GRANT USE CATALOG ON CATALOG prod TO `analysts`;
GRANT USE SCHEMA ON SCHEMA prod.sales TO `analysts`;

-- Inherited SELECT: applies to all current AND future tables in the schema
GRANT SELECT ON SCHEMA prod.sales TO `analysts`;

-- Give data engineers the ability to create and modify objects
GRANT CREATE TABLE, MODIFY ON SCHEMA prod.sales TO `data_engineers`;

-- Inspect effective grants
SHOW GRANTS ON SCHEMA prod.sales;

-- 1. Storage credential wraps a cloud IAM role (created by a metastore admin)
CREATE STORAGE CREDENTIAL uc_storage_cred
  WITH (IAM_ROLE = 'arn:aws:iam::123456789012:role/uc-storage-role')
  COMMENT 'Role trusted by Unity Catalog for lake access';

-- 2. External location binds the credential to a specific path
CREATE EXTERNAL LOCATION landing_zone
  URL 's3://company-lake/landing'
  WITH (STORAGE CREDENTIAL uc_storage_cred)
  COMMENT 'Raw ingestion landing zone';

-- 3. Grant file/creation privileges on the external location
GRANT READ FILES, WRITE FILES ON EXTERNAL LOCATION landing_zone TO `data_engineers`;
GRANT CREATE EXTERNAL TABLE ON EXTERNAL LOCATION landing_zone TO `data_engineers`;

-- 4. Define an external table pointing at data in that location
CREATE TABLE prod.sales.orders_ext
  USING DELTA
  LOCATION 's3://company-lake/landing/orders';

-- 5. Define a governed volume for non-tabular files at the same location
CREATE EXTERNAL VOLUME prod.sales.raw_files
  LOCATION 's3://company-lake/landing/files';
